<script setup lang="ts">
import {ref,onMounted} from 'vue'
const props=defineProps<{space:string;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const rows=ref<any[]>([]),page=ref(1),count=ref(0),busy=ref(false),error=ref(''),message=ref('')
const endpoint=()=>`workspaces/${props.space}/phone-extensions/`
async function load(){busy.value=true;error.value='';rows.value=[];try{const data=await props.request(endpoint()+`?page=${page.value}`);rows.value=data.results.map((row:any)=>({...row,reason:''}));count.value=data.count}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function save(row:any,remove=false){busy.value=true;error.value='';try{await props.request(endpoint(),{membership_id:row.membership_id,extension:row.extension||undefined,...(row.revision===null?{}:{revision:row.revision}),remove,reason:row.reason});message.value='Association locale enregistrée. Aucun appel lancé.';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><h3>Postes Phonetico — association manuelle</h3><p>Configuration locale uniquement : aucune connexion NEWT, aucun appel. Un poste par compte, unique sur ce déploiement. Vérifiez le numéro dans votre PBX. Pour un setter actif dans les deux espaces, la modification exige les droits administrateur dans les deux.</p><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><article v-for="row in rows" :key="row.membership_id"><form @submit.prevent="save(row)"><strong>{{row.username}}</strong><p>{{row.eligible?'Setter actif':'Accès ou compte suspendu : retrait possible uniquement'}}</p><label>Poste<input v-model="row.extension" pattern="[0-9]{1,10}" maxlength="10" :disabled="busy||!row.eligible"></label><label>Motif<input v-model="row.reason" required maxlength="1000" :disabled="busy"></label><button class="secondary" :disabled="busy||!row.eligible||!row.extension">Enregistrer</button><button v-if="row.revision!==null" type="button" class="secondary" :disabled="busy||!row.reason.trim()" @click="save(row,true)">Retirer l’association</button></form></article><p v-if="!rows.length">Aucun setter visible.</p><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button> Page {{page}} <button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button><button class="secondary" :disabled="busy" @click="load">Actualiser</button></section></template>
